var ps;

function setup() {
	createCanvas(600, 600);
	ps = []
	for (let i = 0; i < 100; i++) {
		const x = random(width)
		const y = random(height)
		const dx = random(-2, 2)
		const dy = random(-2, 2)
		const c = color(random(111), random(111), random(333))
		ps.push({x, y, dx, dy, c})
	}

	background(0, 0, 12)
}

function draw() {
	for (let p of ps) {
		p.x += p.dx;
		p.y += p.dy;
		stroke(p.c);
		point(p.x, p.y)
	}
}
